from pathlib import Path
import json
p=Path(__file__).parent;f=json.loads((p/'facts/inputs.json').read_text());s=(p/'report.md').read_text()
r=dict(ticker='BE',as_of='2026-11-04',research_cutoff=f['cutoff'],price=f['price'],price_alternative=f['price_alternative'],price_timestamp=f['price_timestamp'],price_note='Yahoo 200.40 versus StockAnalysis 200.41; no single certified close.',scanner_date=f['scanner_date'],scanner_price=f['scanner_price'],research_status='Audited partial factual research; unresolved limitations retained',bear=None,base=None,bull=None,buy_ceiling=None,owner_fcf=None,equity_bridge=None,approved_entry=False,stage35_approved=False,latestCompleted=False,decision_es='Mejora operativa con financiación, caja y dilución pendientes de normalización; investigación parcial sin entrada.',decision_en='Operating improvement with unresolved financing, cash and dilution normalization; partial research without entry.',publication_note='No normalized owner FCF, integral capital bridge or valuation. Oracle consideration, guarantees and contract funding remain unresolved; next earnings date unconfirmed. Preserve price discrepancies and historical scanner.')
for k,title in [('pros_es','Pros ES'),('cons_es','Contras ES'),('pros_en','Pros EN'),('cons_en','Cons EN')]:r[k]=[x[2:] for x in s.split('### '+title+'\n')[1].split('\n#')[0].strip().splitlines() if x.startswith('- ')]
(p/'publication.json').write_text(json.dumps(r,indent=2,ensure_ascii=False)+'\n')
